/* Авторские задачи ЕГЭ по экспериментам и измерениям. */
(() => {
  const fmt = number => String(Number(number.toFixed(5))).replace('.', ',');
  function scale(start, increment, pointer) {
    const points = [], segments = [];
    for (let tick = 0; tick <= 10; tick++) {
      const x = 70 + 50*tick;
      points.push({id:'base'+tick,x,y:160,label:''}, {
        id:'mark'+tick,x,y:tick%5===0?125:140,
        label:tick%5===0?fmt(start+tick*increment):''
      });
      segments.push({from:'base'+tick,to:'mark'+tick});
    }
    segments.push({from:'base0',to:'base10'});
    if (pointer !== undefined) {
      const x = 70 + 50*pointer;
      points.push({id:'needle',x,y:210,label:'указатель'}, {id:'tip',x,y:173,label:''});
      segments.push({from:'needle',to:'tip'});
    }
    return {geometry:{caption:'Шкала прибора',points,segments}};
  }

  function table(caption, columns, rows) {
    return {dataChart:{kind:'table',caption,columns,rows,labels:[],values:[]}};
  }

  const variants = [
    ['Цена деления шкалы','мл',n=>[
      'Определи цену одного деления шкалы мензурки в миллилитрах. Числа рядом с длинными штрихами обозначают объём.',
      n,
      'Подели разность двух подписанных значений на число промежутков между ними.',
      `Между 0 и ${5*n} мл пять промежутков. Цена деления равна ${5*n}/5 = ${n} мл.`,
      scale(0,n)]],
    ['Показание динамометра','Н',n=>[
      'По рисунку определи показание динамометра в ньютонах. Подписанные значения шкалы приведены в ньютонах.',
      n/2+(3+n%5)/5,
      'Определи цену деления и отсчитай число делений вправо от первой подписанной отметки.',
      `Цена деления 0,2 Н. Указатель расположен на ${3+n%5}-м делении после ${fmt(n/2)} Н. Показание равно ${fmt(n/2+(3+n%5)/5)} Н.`,
      scale(n/2,.2,3+n%5)]],
    ['Приборная погрешность','°C',n=>[
      'Какова абсолютная погрешность отсчёта по шкале термометра, если она равна половине цены деления? Подписанные значения и ответ выражены в °C.',
      n/4,
      'Найди цену деления по соседним подписанным отметкам.',
      `Цена деления равна ${fmt(5*n/2)}/5 = ${fmt(n/2)} °C. Половина даёт ${fmt(n/4)} °C.`,
      scale(0,n/2)]],
    ['Верхняя граница результата','см',n=>[
      `Длина детали записана как (${n+8} ± 0,3) см. Каково наибольшее значение длины в принятом интервале измерения?`,n+8.3,
      'К центральному значению прибавь абсолютную погрешность.',
      `Верхняя граница равна ${n+8} + 0,3 = ${fmt(n+8.3)} см.`]],
    ['Относительная погрешность','%',n=>[
      `Время опыта записано как (${5*n} ± ${fmt(n/10)}) с. Найди относительную погрешность в процентах.`,2,
      'Относительная погрешность равна отношению абсолютной погрешности к центральному результату.',
      `δ = (${fmt(n/10)}/${5*n}) · 100% = 2%.`]],
    ['Среднее показание','с',n=>[
      'В таблице приведены результаты четырёх измерений времени одного и того же процесса. Найди среднее время в секундах.',n+1.5,
      'Сложи четыре измерения и раздели на их число.',
      `Среднее равно (${n} + ${n+1} + ${n+2} + ${n+3})/4 = ${fmt(n+1.5)} с.`,
      table('Повторные измерения времени',['Опыт','Время, с'],[0,1,2,3].map((k,i)=>[i+1,n+k]))]],
    ['Проверка закона Гука','Н/м',n=>[
      'Пружину растягивают в пределах упругости. По данным таблицы найди её жёсткость в Н/м.',100+5*n,
      'Определи отношение силы к удлинению, переведя сантиметры в метры.',
      `При удлинении 2 см сила равна ${fmt(2+n/10)} Н. Тогда k = ${fmt(2+n/10)}/0,02 = ${100+5*n} Н/м.`,
      table('Сила и удлинение',['Удлинение, см','Сила, Н'],[0,1,2,3].map(x=>[x,fmt(x*(1+n/20))]))]],
    ['Границы разности двух отсчётов','г',n=>[
      `Масса сосуда с жидкостью равна (${60+5*n} ± 1) г, пустого сосуда — (60 ± 2) г. Какой может быть наименьшая масса жидкости в граммах в пределах указанных интервалов?`,5*n-3,
      'Для минимальной разности возьми наименьшее значение первой массы и наибольшее значение второй.',
      `m = (${60+5*n} − 1) − (60 + 2) = ${5*n-3} г.`]],
    ['Контроль переменных','',n=>{
      const resistance=5+n;
      const rows=[[1,6,resistance,'20'],[2,9,resistance,'20'],[3,6,resistance+3,'20'],[4,9,resistance,'40']];
      const order=rows.slice(n%4).concat(rows.slice(0,n%4));
      const second=order.findIndex(row=>row[0]===2)+1;
      const first=order.findIndex(row=>row[0]===1)+1;
      return [
        `Ученик уже провёл опыт № ${first}. Он хочет изучить влияние напряжения на ток и сохранить сопротивление и температуру прежними. Укажи номер подходящего второго опыта.`,second,
        'Сравни сопротивление и температуру каждой строки с исходным опытом.',
        `В опыте № ${second} сопротивление осталось ${resistance} Ом, температура — 20 °C, а напряжение изменилось с 6 до 9 В.`,
        table('План измерений',['Опыт','Напряжение, В','Сопротивление, Ом','Температура, °C'],order.map((row,i)=>[i+1,...row.slice(1)]))
      ];
    }],
    ['Плотность по измеренным данным','г/см³',n=>[
      'По результатам взвешивания и измерения объёма вычисли плотность образца. Ответ дай в г/см³.',
      2+n/10,
      'Плотность равна массе, делённой на объём.',
      `По таблице ρ = ${20*n+n*n}/${10*n} = ${fmt(2+n/10)} г/см³.`,
      table('Данные об образце',['Величина','Значение'],[['Масса, г',20*n+n*n],['Объём, см³',10*n]])]]
  ];

  for (const [index,[title,unit,build]] of variants.entries()) {
    for (let variant=1; variant<=15; variant++) {
      const [question, rawAnswer, plan, calculation, figure] = build(variant+1);
      const steps = [plan, calculation];
      const category = index===7 ? 268 : 377;
      tasks.push({
        id: `ege-physics-experiment-${index+1}-${variant}`,
        grade:11, domain:'physics', subject:'physics', exam:'ege', topic:0,
        topicName:'Эксперимент и измерения', examTopic:'physics-ege-experiment',
        level:index<3?0:index<7?1:2,
        title, question, unit, answer:Number(rawAnswer.toFixed(5)), figure,
        hints:[plan], steps, solution:steps.join(' '), review:{plan},
        source:{
          name:'Решу ЕГЭ', id:'Эксперимент и измерения', type:'тематический каталог',
          url:`https://phys-ege.sdamgia.ru/test?category_id=${category}&filter=all`,
          note:'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

